namespace RonSijm.FluidHumidifier.Factories.RedshiftServerless;

public class InnerWorkgroupWorkgroupFactory(Action<Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup> factoryAction = null) : SubResourceFactory<Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup>
{

    internal List<InnerWorkgroupConfigParameterFactory> ConfigParametersFactories { get; set; } = [];

    internal InnerWorkgroupEndpointFactory EndpointFactory { get; set; }

    internal InnerWorkgroupPerformanceTargetFactory PricePerformanceTargetFactory { get; set; }

    protected override Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup Create()
    {
        var workgroupResult = CreateWorkgroup();
        factoryAction?.Invoke(workgroupResult);

        return workgroupResult;
    }

    private Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup CreateWorkgroup()
    {
        var workgroupResult = new Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup();

        return workgroupResult;
    }
    public override void CreateChildren(Humidifier.RedshiftServerless.WorkgroupTypes.Workgroup result)
    {
        base.CreateChildren(result);

        result.ConfigParameters = ConfigParametersFactories.Any() ? ConfigParametersFactories.Select(x => x.Build()).ToList() : null;
        result.Endpoint ??= EndpointFactory?.Build();
        result.PricePerformanceTarget ??= PricePerformanceTargetFactory?.Build();
    }

} // End Of Class

